UPDATE label_templates t SET spec=p.new_spec,revision=t.revision+1,updated_at=now()
FROM presets p WHERE t.seed_key=p.seed_key AND t.name=p.name AND t.spec=p.old_spec
  AND t.revision=1 AND t.enabled=true AND t.chz_product_group_codes IS NULL
  AND t.purpose='pallet' AND t.format='pallet_sheet_v2';
