INSERT INTO label_templates(tenant_id,seed_key,name,purpose,format,spec)
SELECT o.id, CASE WHEN EXISTS(SELECT 1 FROM label_templates b WHERE b.tenant_id=o.id AND b.seed_key=p.seed_key)
  THEN p.seed_key||'-2026-10' ELSE p.seed_key END,
  CASE WHEN EXISTS(SELECT 1 FROM label_templates b WHERE b.tenant_id=o.id AND b.seed_key=p.seed_key) THEN p.name||' · обновлённый стандарт' ELSE p.name END, 'pallet','pallet_sheet_v2',p.new_spec
FROM organization o CROSS JOIN presets p
WHERE NOT EXISTS(SELECT 1 FROM label_templates t WHERE t.tenant_id=o.id AND t.seed_key=p.seed_key
  AND t.spec=p.new_spec AND t.name=p.name AND t.enabled=true AND t.chz_product_group_codes IS NULL
  AND t.purpose='pallet' AND t.format='pallet_sheet_v2')
ON CONFLICT(tenant_id,seed_key) DO NOTHING;
